INSERT INTO hotels (id, name, address, city_province, average_rating, description, refund_policy_id, check_in_time, check_out_time, created_at, updated_at) VALUES ('e0000000-0000-0000-0000-000000000001', 'Vinpearl Resort & Spa', 'Đồi Quan Tẩm, Sa Pa', 'Sa Pa', 5, 'Khu nghỉ dưỡng cao cấp ven biển, cung cấp các villa sang trọng có hồ bơi riêng, mang lại sự riêng tư tuyệt đối.', '00000000-0000-0000-0000-000000000002', '14:00:00', '12:00:00', NOW(), NOW());
INSERT INTO hotels (id, name, address, city_province, average_rating, description, refund_policy_id, check_in_time, check_out_time, created_at, updated_at) VALUES ('e0000000-0000-0000-0000-000000000002', 'Mường Thanh Luxury', 'Trần Hưng Đạo, Dương Đông', 'Phú Quốc', 5, 'Cung cấp trải nghiệm trọn vẹn với các tiện ích giải trí đa dạng như quầy bar tầng thượng, phòng gym và khu vui chơi trẻ em.', '00000000-0000-0000-0000-000000000002', '14:00:00', '12:00:00', NOW(), NOW());
INSERT INTO hotels (id, name, address, city_province, average_rating, description, refund_policy_id, check_in_time, check_out_time, created_at, updated_at) VALUES ('e0000000-0000-0000-0000-000000000003', 'InterContinental', 'Đồi Quan Tẩm, Sa Pa', 'Sa Pa', 3, 'Nghỉ dưỡng đẳng cấp 5 sao với tầm nhìn tuyệt đẹp, tiện ích sang trọng và phong cách phục vụ chuẩn quốc tế.', '00000000-0000-0000-0000-000000000002', '14:00:00', '12:00:00', NOW(), NOW());
INSERT INTO hotels (id, name, address, city_province, average_rating, description, refund_policy_id, check_in_time, check_out_time, created_at, updated_at) VALUES ('e0000000-0000-0000-0000-000000000004', 'Novotel', 'Hoàng Liên, Sa Pa', 'Sa Pa', 4, 'Khách sạn mang đậm dấu ấn kiến trúc cổ điển pha lẫn hiện đại, không gian lãng mạn và dịch vụ tận tâm.', '00000000-0000-0000-0000-000000000002', '14:00:00', '12:00:00', NOW(), NOW());
INSERT INTO hotels (id, name, address, city_province, average_rating, description, refund_policy_id, check_in_time, check_out_time, created_at, updated_at) VALUES ('e0000000-0000-0000-0000-000000000005', 'Pullman', '1 Thanh Niên, Tây Hồ', 'Hà Nội', 4, 'Trải nghiệm không gian yên bình, thiết kế hòa mình vào thiên nhiên cùng dịch vụ Spa chăm sóc sức khỏe tuyệt vời.', '00000000-0000-0000-0000-000000000002', '14:00:00', '12:00:00', NOW(), NOW());
INSERT INTO hotels (id, name, address, city_province, average_rating, description, refund_policy_id, check_in_time, check_out_time, created_at, updated_at) VALUES ('e0000000-0000-0000-0000-000000000006', 'The Reverie Saigon', 'Đồi Quan Tẩm, Sa Pa', 'Sa Pa', 4, 'Tận hưởng kỳ nghỉ trong mơ với bãi biển riêng tư, hải sản tươi ngon và các hoạt động thể thao dưới nước đầy thú vị.', '00000000-0000-0000-0000-000000000002', '14:00:00', '12:00:00', NOW(), NOW());
